@property
def is_fixed(self) -> bool:
    """Whether the boundary regime constrains the plasma edge at all."""

    return self.boundary_condition == "fixed"

@property
def regime_strength(self) -> float:
    """Scalar ladder position: 0 for free boundary, growing with constraint."""

    if not self.is_fixed:
        return 0.0
    edge_response = 1.0 / (1.0 + self.boundary_stiffness)
    return float(1.0 - edge_response)

def interval_profiles(self, centers: np.ndarray) -> dict[str, np.ndarray]:
    """Return the interval-wise boundary profiles consumed downstream.

    Both profiles are resolved per radial interval so that the coefficient,
    operator and interval-energy stages can share exactly the same boundary
    meaning instead of re-deriving (or averaging away) the regime.
    """

    centers = np.asarray(centers, dtype=float)
    response = validate_boundary_profile(
        self.response_profile(centers), name="boundary_response"
    )
    closure = validate_boundary_profile(
        self.closure_profile(centers), name="boundary_closure"
    )
    return {"boundary_response": response, "boundary_closure": closure}

