            else {name: np.asarray(value, dtype=float) for name, value in self.boundary_weights.items()}
        )
        shapes = {value.shape for value in coeffs.values()}
        if len(shapes) != 1:
            raise ValueError("all coefficient arrays must share one shape.")
        for name, value in coeffs.items():
            if value.ndim != 3:
                raise ValueError(f"{name} must be a rank-3 array.")
        if coeffs:
            reference = next(iter(coeffs.values())).shape
            pair_shape = reference[:2]
            interval_shape = reference[2:]
            for name, value in pair_policy.items():
                if value.shape != pair_shape:
                    raise ValueError(f"pair policy {name} must have shape {pair_shape}.")
            for name, value in boundary_weights.items():
                if value.shape != interval_shape:
                    raise ValueError(f"boundary weight {name} must have shape {interval_shape}.")
        object.__setattr__(self, "coefficients", coeffs)
        object.__setattr__(self, "profiles", profiles)
        object.__setattr__(self, "pair_policy", pair_policy)
        object.__setattr__(self, "boundary_weights", boundary_weights)

    def get(self, name: str) -> np.ndarray:
        if name in self.coefficients:
            return self.coefficients[name]
        if name in self.profiles:
            return self.profiles[name]
        raise KeyError(name)

    def boundary_weight(self, name: str) -> np.ndarray:
        """Return the interval-wise boundary weight applied to one family."""

        weights = self.boundary_weights or {}
        if name in weights:
            return weights[name]
        intervals = next(iter(self.coefficients.values())).shape[2] if self.coefficients else 0
        return np.ones(intervals)

    def as_legacy_dict(self) -> dict[str, np.ndarray]:
        data = dict(self.coefficients)
        data.update(self.profiles)
        data["pair_policy"] = self.pair_policy
        data["boundary_weights"] = self.boundary_weights
        return data

